#[verifier::spec]
fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    // Precondition: The input array can be of any length, including zero.
    requires(true);

    // The output vector must contain only even numbers.
    ensures(
        |result: &Vec<i32>| {
            forall(|i: usize| {
                implies(i < result.len(), result[i] % 2 == 0)
            })
        }
    );

    // Ensures that every even number in the input array appears at least once in the output vector.
    ensures(
        |result: &Vec<i32>| {
            forall(|x: i32| {
                implies(
                    exists(|j: usize| j < arr.len() && arr[j] == x && x % 2 == 0),
                    exists(|k: usize| k < result.len() && result[k] == x)
                )
            })
        }
    );

    // Ensures that if the input array is empty or contains no even numbers, the output is an empty vector.
    ensures(
        |result: &Vec<i32>| {
            implies(
                arr.len() == 0 || !exists(|j: usize| j < arr.len() && arr[j] % 2 == 0),
                result.len() == 0
            )
        }
    );

    // Invariant: The output vector is constructed from the input array.
    invariant(
        |result: &Vec<i32>| {
            forall(|i: usize| {
                implies(i < result.len(), exists(|j: usize| j < arr.len() && arr[j] == result[i]))
            })
        }
    );

    // Decreases clause: The length of the input array decreases as we process it.
    decreases(arr.len());

    // Function body
    let mut result = Vec::new();
    for &num in arr.iter() {
        if num % 2 == 0 {
            result.push(num);
        }
    }
    result
}